-- Keep legacy identifiers and raw document bytes importable.
CREATE TABLE announcement_categories(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name varchar(100) NOT NULL UNIQUE,active boolean NOT NULL DEFAULT true,created_at bigint NOT NULL,revision integer NOT NULL DEFAULT 1);
INSERT INTO announcement_categories(name,created_at) VALUES('فرهنگی',0),('کاری',0),('تکنولوژی',0);
CREATE TABLE announcement_items(content_id bigint PRIMARY KEY REFERENCES contents(id) ON DELETE CASCADE,category_id bigint REFERENCES announcement_categories(id),delivery_mode varchar(20) NOT NULL DEFAULT 'bank',creation_key varchar(64) UNIQUE);
CREATE INDEX announcement_items_category ON announcement_items(category_id,content_id);
CREATE TABLE announcement_subscriptions(user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,category_id bigint NOT NULL REFERENCES announcement_categories(id),created_at bigint NOT NULL,PRIMARY KEY(user_id,category_id));
CREATE INDEX announcement_followers ON announcement_subscriptions(category_id,user_id);
CREATE TABLE announcement_dispatches(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,content_id bigint NOT NULL REFERENCES contents(id),content_version integer NOT NULL,category_id bigint REFERENCES announcement_categories(id),audience varchar(20) NOT NULL,max_user_id bigint NOT NULL,cursor_id bigint NOT NULL DEFAULT 0,state varchar(20) NOT NULL DEFAULT 'pending',created_by bigint NOT NULL REFERENCES admins(id),created_at bigint NOT NULL,UNIQUE(content_id,content_version,audience));
CREATE INDEX announcement_pending ON announcement_dispatches(state,id);
CREATE TABLE advanced_contents(content_id bigint PRIMARY KEY REFERENCES contents(id) ON DELETE CASCADE,document text NOT NULL,revision integer NOT NULL DEFAULT 1,updated_at bigint NOT NULL);
CREATE TABLE advanced_revisions(content_id bigint NOT NULL REFERENCES contents(id),version integer NOT NULL,document text NOT NULL,created_at bigint NOT NULL,PRIMARY KEY(content_id,version));
CREATE TABLE advanced_files(content_id bigint NOT NULL REFERENCES contents(id),file_id bigint NOT NULL REFERENCES files(id),PRIMARY KEY(content_id,file_id));
CREATE TABLE content_templates(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title varchar(200) NOT NULL,kind varchar(30) NOT NULL,document text NOT NULL,created_by bigint NOT NULL REFERENCES admins(id),created_at bigint NOT NULL);
CREATE TABLE interaction_values(user_id bigint NOT NULL REFERENCES users(id),content_id bigint NOT NULL REFERENCES contents(id),block_key varchar(80) NOT NULL,value bigint NOT NULL DEFAULT 0,updated_at bigint NOT NULL,PRIMARY KEY(user_id,content_id,block_key));
-- Opaque, user-bound, one-use actions prevent double toggle/increment on replay.
CREATE TABLE message_actions(token varchar(24) PRIMARY KEY,user_id bigint NOT NULL REFERENCES users(id),content_id bigint NOT NULL REFERENCES contents(id),content_version integer NOT NULL,block_index integer NOT NULL,item_index integer NOT NULL,expires_at bigint NOT NULL,consumed boolean NOT NULL DEFAULT false);
CREATE INDEX message_actions_expiry ON message_actions(expires_at);
CREATE TABLE telegram_media(file_id bigint NOT NULL REFERENCES files(id),bot_hash varchar(64) NOT NULL,kind varchar(20) NOT NULL,telegram_file_id varchar(512) NOT NULL,unique_id varchar(200) NOT NULL DEFAULT '',updated_at bigint NOT NULL,PRIMARY KEY(file_id,bot_hash,kind));
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='unibot_app') THEN
 GRANT SELECT,INSERT,UPDATE,DELETE ON announcement_categories,announcement_items,announcement_subscriptions,announcement_dispatches,advanced_contents,advanced_revisions,advanced_files,content_templates,interaction_values,message_actions,telegram_media TO unibot_app;
 GRANT USAGE ON SEQUENCE announcement_categories_id_seq,announcement_dispatches_id_seq,content_templates_id_seq TO unibot_app;
END IF;END $$;
CREATE TABLE telegram_send_limits(scope varchar(100) PRIMARY KEY,ready_at timestamptz NOT NULL);
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='unibot_app') THEN GRANT SELECT,INSERT,UPDATE ON telegram_send_limits TO unibot_app; END IF; END $$;
